"use client";
import axiosInstance from "@/api/axiosInstance";
import React, { useEffect, useState } from 'react';

export default function ContentPage() {
    const [data, setData] = useState(null);
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState(null);

    const fetchData = async () => {
        try {
            const response = await axiosInstance.get('/api/content');
            setData(response.data);
            setLoading(false);
        } catch (error) {
            setError(error);
            setLoading(false);
        }
    };

    useEffect(() => {
        fetchData();
    }, []);

    if (loading) {
        return <div className="min-h-screen flex items-center justify-center">Loading...</div>;
    }

    if (error) {
        return <div className="min-h-screen flex items-center justify-center">Error: {error.message}</div>;
    }

    return (
        <div className="min-h-screen flex flex-col items-center justify-center bg-gray-100 p-6">
            <h1 className="text-2xl font-bold mb-4">Content Page</h1>
            <div className="grid gap-4 grid-cols-1 sm:grid-cols-2 lg:grid-cols-3">
                {data && data.map((item) => (
                    <div key={item._id} className="p-20 bg-blue-950 rounded-2xl shadow-md">
                        <h2 className="text-2xl font-bold text-white">{item.title}</h2>
                        <p className="text-white">{item.description}</p>
                        <p className="text-white " > {item.body}</p>
                        <p className="text-white">Posted by: {item.username}</p>
                    </div>
                ))}
            </div>
        </div>
    );
}
